1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const HIGH_ENCHANTMENT_LEVEL = 5;
54	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
58	
59	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	/** An item's insurance value — what it is insured FOR, as opposed to what
69	 *  insuring it costs. The cap is derived from these, never from premiums. */
70	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
71	  sword: 1000,
72	  amulet: 600,
73	  staff: 800,
74	  potion: 400,
75	  rune: 250,
76	  moonstone: 250,
77	};
78	
79	const DEDUCTIBLE = 100;
80	const CAP_MULTIPLE = 2;
81	
82	/** Modifiers are expressed as an amount to add, never as a factor to multiply
83	 *  by, so that they stay additive against their base and so that the integer
84	 *  numerator keeps float artifacts out of the final rounding
85	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
86	const percentOf = (amount: number, percent: number): number =>
87	  (amount * percent) / 100;
88	
89	/** Rounds up — premiums round in the MHPCO's favour. */
90	const roundPremium = (amount: number): number => Math.ceil(amount);
91	
92	const COMPONENT_BLOCK_SIZE = 3;
93	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
94	
95	const COMPONENT_TYPES = ["rune", "moonstone"];
96	
97	const isComponent = (item: Item): boolean =>
98	  COMPONENT_TYPES.includes(item.type);
99	
100	const itemBasePremium = (item: Item): number =>
101	  BASE_PREMIUM_BY_TYPE[item.type];
102	
103	const countByType = (items: Item[]): Map<string, number> => {
104	  const counts = new Map<string, number>();
105	  for (const item of items) {
106	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
107	  }
108	  return counts;
109	};
110	
111	/** A block is exactly three alike components, priced as a unit rather than
112	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
113	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
114	  count === COMPONENT_BLOCK_SIZE
115	    ? COMPONENT_BLOCK_BASE_PREMIUM
116	    : count * BASE_PREMIUM_BY_TYPE[type];
117	
118	const sum = (amounts: number[]): number =>
119	  amounts.reduce((total, amount) => total + amount, 0);
120	
121	const policyBasePremium = (items: Item[]): number => {
122	  const mainItems = items.filter((item) => !isComponent(item));
123	  const componentGroups = [...countByType(items.filter(isComponent))];
124	
125	  return (
126	    sum(mainItems.map(itemBasePremium)) +
127	    sum(componentGroups.map(componentGroupBasePremium))
128	  );
129	};
130	
131	interface ItemModifierRule {
132	  appliesTo: (item: Item) => boolean;
133	  percent: number;
134	}
135	
136	/** Every item-scoped modifier, as a rule that either applies to an item or
137	 *  does not. Applicable rules stack. */
138	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
139	  {
140	    appliesTo: (item) => item.cursed === true,
141	    percent: CURSE_SURCHARGE_PERCENT,
142	  },
143	  {
144	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
145	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
146	  },
147	];
148	
149	/** Item-scoped modifiers apply to the affected item's own base premium,
150	 *  not to the policy total. */
151	const itemModifierAmount = (item: Item): number =>
152	  sum(
153	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
154	      percentOf(itemBasePremium(item), rule.percent),
155	    ),
156	  );
157	
158	/** A policy written by a quote step, as later claim steps see it. */
159	interface Policy {
160	  remainingCap: number;
161	}
162	
163	/** What a step leaves behind for the steps after it. Steps are not
164	 *  independent: a quote is priced against how many contracts precede it, and
165	 *  a claim is paid against a policy an earlier quote wrote, so running a
166	 *  scenario threads this state from each step to the next. */
167	interface ScenarioState {
168	  customer: Customer;
169	  precedingContracts: number;
170	  /** Keyed by the zero-based index of the quote step that wrote the policy —
171	   *  which is what a claim step's `policy` field refers to. */
172	  policiesByStep: Record<number, Policy>;
173	}
174	
175	const initialState = (customer: Customer): ScenarioState => ({
176	  customer,
177	  precedingContracts: 0,
178	  policiesByStep: {},
179	});
180	
181	/** A step's outcome: what it reports, and the state the next step sees. */
182	interface StepOutcome {
183	  result: StepResult;
184	  state: ScenarioState;
185	}
186	
187	/** What a policy-wide rule may look at: the customer, plus where this quote
188	 *  sits in the customer's history of contracts. A pricing view of the
189	 *  scenario state — rules read it, they never advance it. */
190	type PolicyContext = Readonly<ScenarioState>;
191	
192	interface PolicyModifierRule {
193	  appliesTo: (context: PolicyContext) => boolean;
194	  /** Signed: positive surcharges, negative discounts. */
195	  percent: number;
196	}
197	
198	/** Every policy-wide modifier, as a rule that either applies to a policy or
199	 *  does not. Applicable rules stack. */
200	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
201	  {
202	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
203	    percent: -LOYALTY_DISCOUNT_PERCENT,
204	  },
205	  {
206	    appliesTo: () => true,
207	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
208	  },
209	  {
210	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
211	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
212	  },
213	];
214	
215	/** Policy-wide modifiers apply to the policy base premium — the sum of every
216	 *  item's base premium — not to any single item. */
217	const policyModifierAmount = (
218	  basePremium: number,
219	  context: PolicyContext,
220	): number =>
221	  sum(
222	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
223	      (rule) => percentOf(basePremium, rule.percent),
224	    ),
225	  );
226	
227	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
228	  const basePremium = policyBasePremium(items);
229	  // Every modifier is an amount added to the base premium, not a factor
230	  // compounded onto a running total: item-scoped modifiers take a percentage
231	  // of their own item's base premium, policy-wide ones take a percentage of
232	  // the policy base premium.
233	  const modifierAmounts = [
234	    ...items.map(itemModifierAmount),
235	    policyModifierAmount(basePremium, context),
236	  ];
237	  // The processing fee is added last, after all percentage modifiers.
238	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
239	  return { premium: roundPremium(premium) };
240	};
241	
242	/** The cap on everything a policy will ever pay out: twice the sum of the
243	 *  insured items' values. Premium modifiers do not raise it. */
244	const policyCap = (items: Item[]): number =>
245	  CAP_MULTIPLE *
246	  sum(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
247	
248	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
249	  const policy = state.policiesByStep[step.policy];
250	  const payout = sum(
251	    step.incident.damages.map((damage) => damage.amount - DEDUCTIBLE),
252	  );
253	  const remainingCap = policy.remainingCap - payout;
254	  return {
255	    result: { payout, remainingCap },
256	    state: {
257	      ...state,
258	      policiesByStep: {
259	        ...state.policiesByStep,
260	        [step.policy]: { remainingCap },
261	      },
262	    },
263	  };
264	};
265	
266	const runStep = (
267	  step: Step,
268	  stepIndex: number,
269	  state: ScenarioState,
270	): StepOutcome => {
271	  if (step.op === "quote")
272	    return {
273	      result: quote(step.items, state),
274	      state: {
275	        ...state,
276	        // Each quote written becomes a preceding contract for the next one.
277	        precedingContracts: state.precedingContracts + 1,
278	        policiesByStep: {
279	          ...state.policiesByStep,
280	          [stepIndex]: { remainingCap: policyCap(step.items) },
281	        },
282	      },
283	    };
284	  return claim(step, state);
285	};
286	
287	export const runScenario = (scenario: Scenario): ScenarioResult => {
288	  const { results } = scenario.steps.reduce(
289	    ({ results, state }, step, stepIndex) => {
290	      const outcome = runStep(step, stepIndex, state);
291	      return { results: [...results, outcome.result], state: outcome.state };
292	    },
293	    { results: [] as StepResult[], state: initialState(scenario.customer) },
294	  );
295	  return { results };
296	};
